from common_e15 import *
import numpy as np
from geometry_e13 import single_geometry

CHANNELS=[('centered_X','(X-visible_area_centroid_X)/60','mm/60mm','VISIBLE_DOMAIN_NORMALIZED_FEATURES'),('centered_Y','(Y-visible_area_centroid_Y)/60','mm/60mm','VISIBLE_DOMAIN_NORMALIZED_FEATURES'),('centered_Z','(Z-visible_area_centroid_Z)/60','mm/60mm','VISIBLE_DOMAIN_NORMALIZED_FEATURES'),('normal_X','normalized visible triangle cross-product sum X','1','LOCAL_DIFFERENTIAL_GEOMETRY_FEATURES'),('normal_Y','normalized visible triangle cross-product sum Y','1','LOCAL_DIFFERENTIAL_GEOMETRY_FEATURES'),('normal_Z','normalized visible triangle cross-product sum Z','1','LOCAL_DIFFERENTIAL_GEOMETRY_FEATURES'),('span_X','visible peak-to-peak X/60','mm/60mm','GLOBAL_SHAPE_FEATURES'),('span_Y','visible peak-to-peak Y/60','mm/60mm','GLOBAL_SHAPE_FEATURES'),('span_Z','visible peak-to-peak Z/60','mm/60mm','GLOBAL_SHAPE_FEATURES'),('load_X','1','1','FIXED_PHYSICAL_METADATA'),('load_Y','0','1','FIXED_PHYSICAL_METADATA'),('load_Z','0','1','FIXED_PHYSICAL_METADATA'),('surface_tag','0: front face','1','FIXED_PHYSICAL_METADATA'),('local_relief','Z-mean Z of 16 visible nearest neighbors','mm','LOCAL_DIFFERENTIAL_GEOMETRY_FEATURES'),('normal_variation','norm(n-mean visible nearest-neighbor normals)','1','LOCAL_DIFFERENTIAL_GEOMETRY_FEATURES'),('log_area','log(1+visible incident-triangle lumped area)','log(1+mm2)','LOCAL_DIFFERENTIAL_GEOMETRY_FEATURES'),('normal_X_std','std visible normal_X','1','GLOBAL_SHAPE_FEATURES'),('normal_Y_std','std visible normal_Y','1','GLOBAL_SHAPE_FEATURES'),('relief_span','visible peak-to-peak Z/60','mm/60mm','GLOBAL_SHAPE_FEATURES')]

def main():
 assert read(R/'00_historical_integrity/INTEGRITY_PASS.json')['passed'];gate();top=[];windows=[];cores=[];geometry=[];edge_reg=[];contract=[]
 for i,(n,formula,unit,cat) in enumerate(CHANNELS):contract.append(dict(channel=i,name=n,formula=formula,units=unit,category=cat,normalization='fixed /60 mm' if i in [0,1,2,6,7,8,18] else 'see formula',support='visible triangles and vertices only',local=i in [3,4,5,13,14,15],visible_global=i in [0,1,2,6,7,8,16,17,18],partial_available=True,deployment='requires declared loading axis and observed geometry; no hidden full geometry',oracle_replace=i in [0,1,2,6,7,8,16,17,18]))
 table(R/'FEATURE_DEPENDENCY_CONTRACT.csv',contract)
 for rr in rows(R/'SOURCE_CORE_REGISTRY.csv'):
  sid=rr['source_id'];g=dict(np.load(rr['source_geometry_path']));s=dict(np.load(J/'03_source_geometry'/(sid+'_SUPPORT.npz')));x=g['xyz'];q=np.flatnonzero(s['core']&s['valid']);tid=s['tile_id'][q];coreids=g['source_ids'][q];out=R/'02_source_geometry'/sid;out.mkdir(exist_ok=True)
  # Reconstruct actual canonical T0 edge adjacency, restricted to the immutable core.
  tri=g['triangles'];ed=np.concatenate([tri[:,[0,1]],tri[:,[1,2]],tri[:,[0,2]]]);ed=np.unique(np.sort(ed,axis=1),axis=0);ed=ed[np.all(s['core'][ed]&s['valid'][ed],axis=1)];inv=np.full(len(x),-1,dtype='i8');inv[q]=np.arange(len(q));pairs=inv[ed];dist=np.linalg.norm(x[ed[:,0]]-x[ed[:,1]],axis=1);dx=x[ed[:,1],0]-x[ed[:,0],0];dy=x[ed[:,1],1]-x[ed[:,0],1];xedge=(abs(dx)>1e-8)&(abs(dy)<1e-8)
  np.savez_compressed(out/'ADJACENCY.npz',pairs=pairs,original_rows=ed,source_ids=g['source_ids'][ed],distance_mm=dist,x_axis_edge=xedge,tile_id=tid,query_original_rows=q)
  edge_reg.append(dict(source_id=sid,path=str(out/'ADJACENCY.npz'),edges=len(ed),horizontal_edges=int(xedge.sum()),original_boundary_edges=int(np.sum(tid[pairs[:,0]]!=tid[pairs[:,1]])),SHA256=sha(out/'ADJACENCY.npz')))
  corefile=out/'CORE.npz';np.savez_compressed(corefile,source_ids=coreids,xyz=x[q],area=s['area'][q],query_original_rows=q,tile_id=tid,region=s.get('region',np.zeros(len(x)))[q]);cores.append(dict(source_id=sid,path=str(corefile),SHA256=sha(corefile),core_points=len(q)))
  for tile in np.unique(tid):
   rowsq=q[tid==tile];xx=x[rowsq,0];center=(xx.min()+xx.max())/2;np.save(out/('QUERY_'+str(tile)+'.npy'),g['source_ids'][rowsq]);top.append(dict(source_id=sid,tile=int(tile),center_X_mm=center,center_Y_mm=float(np.mean(x[rowsq,1])),center_Z_mm=float(np.mean(x[rowsq,2])),query_X_min_mm=xx.min(),query_X_max_mm=xx.max(),query_points=len(rowsq),query_ID_path=str(out/('QUERY_'+str(tile)+'.npy')),nominal_spacing_mm=8.,overlap_total_mm=2.,overlap_fraction=.25,shift_X_mm=2.,FULL_actual_tile_id=0,restricted_assignment='hard original X ownership; no overlap',overlap_query_min_mm=max(x[q,0].min(),xx.min()-1.),overlap_query_max_mm=min(x[q,0].max(),xx.max()+1.)))
   for condition,width in [('X50',50.),('X43',43.)]:
    lower=max(x[:,0].min(),center+2-width/2);upper=min(x[:,0].max(),center+2+width/2);ids=np.flatnonzero((x[:,0]>=lower-1e-8)&(x[:,0]<=upper+1e-8));visible=np.zeros(len(x),bool);visible[ids]=True;invv=np.full(len(x),-1,dtype='i8');invv[ids]=np.arange(len(ids));tt=invv[tri[np.all(visible[tri],axis=1)]];vg=single_geometry(x[ids],tt,g['source_ids'][ids]);assert visible[rowsq].all();assert np.isfinite(vg['features']).all();p=out/(condition+'_SHIFT_'+str(tile)+'.npz');np.savez(p,**vg)
    windows.append(dict(source_id=sid,condition=condition,tile=int(tile),variant='SHIFT',center_X_mm=center+2,declared_min_mm=lower,declared_max_mm=upper,actual_min_mm=x[ids,0].min(),actual_max_mm=x[ids,0].max(),visible_points=len(ids),context_points=len(vg['context']),query_margin_mm=float(np.minimum(x[rowsq,0]-x[ids,0].min(),x[ids,0].max()-x[rowsq,0]).min()),geometry_path=str(p),SHA256=sha(p),hidden_geometry=False))
   print('SHIFT_GEOMETRY',sid,int(tile),flush=True)
  # FULL has no second physical full-view window. Alternate CDF phase is a sampling-only control.
  order=np.lexsort((x[:,2],x[:,1],x[:,0]));cdf=np.cumsum(g['area'][order])/sum(g['area']);alt=order[np.searchsorted(cdf,(np.arange(4096)+.75)/4096).clip(0,len(x)-1)];assert len(np.unique(alt))==4096;np.save(out/'FULL_SHIFT_CONTEXT.npy',alt)
 table(R/'ORIGINAL_TILE_TOPOLOGY.csv',top);table(R/'06_query_tile_geometry/ADJACENCY_REGISTRY.csv',edge_reg);table(R/'02_source_geometry/CORE_REGISTRY.csv',cores);table(R/'07_same_point_contexts/SHIFT_GEOMETRY_REGISTRY.csv',windows)
 def assignments():
  for a in cores:
   d=dict(np.load(a['path']))
   for i in range(len(d['source_ids'])):yield dict(source_id=a['source_id'],source_point_id=int(d['source_ids'][i]),original_query_tile=int(d['tile_id'][i]),FULL_actual_owner=0)
 table(R/'ORIGINAL_QUERY_ASSIGNMENT.csv',assignments());write(R/'04_intervention_preregistration/GEOMETRY_READY.json',dict(UTC=now(),passed=True,sources=13,shift_windows=len(windows),geometry_only=True));print('GEOMETRY_READY',flush=True)
if __name__=='__main__':main()
